function digitCount(num) {
  const count = new Array(10).fill(0);
  for (const ch of num) {
    count[Number(ch)]++;
  }
  for (let i = 0; i < num.length; i++) {
    if (count[i] !== Number(num[i])) {
      return false;
    }
  }
  return true;
}

