function digitCount(num) {
  // For every index, scan the whole string again and compare the tally with the digit there.
  let ok = true;
  for (let i = 0; i < num.length; i++) {
    let seen = 0;
    for (let j = 0; j < num.length; j++) if (num.charCodeAt(j) - 48 === i) seen++;
    if (seen !== num.charCodeAt(i) - 48) ok = false;
  }
  return ok;
}

