function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  // The strings that describe themselves; true answers are rare, so the generator plants them on purpose.
  const good = ['1210', '2020', '21200', '3211000', '42101000', '521001000', '6210001000'];
  const mode = pick(3);
  if (mode === 0) return [good[pick(good.length)]];
  if (mode === 1) {
    const digits = [...good[pick(good.length)]];
    const i = pick(digits.length);
    digits[i] = String((Number(digits[i]) + 1 + pick(9)) % 10);
    return [digits.join('')];
  }
  const n = size === 'large' ? 10 : 1 + pick(10);
  const top = rand() < 0.7 ? 4 : 10;
  return [Array.from({ length: n }, () => String(pick(top))).join('')];
}
